/**
 * Serialize a property wrapped in its own named XML element.
 */
template <typename T, typename SerializeT>
common::optional<SerializationError> SerializePropertyAsElement(
  const std::string& name,
  const T& value,
  SelfClosingWriter& writer,
  iteration::Property property,
  const SerializeT& serialize_value
) {
  writer.StartElement(name);
  if (writer.error().has_value()) {
    return writer.move_error();
  }

  common::optional<SerializationError> error = serialize_value(value, writer);
  if (error.has_value()) {
    error->path.segments.emplace_front(
      common::make_unique<iteration::PropertySegment>(property)
    );
    return error;
  }

  writer.StopElement(name);
  if (writer.error().has_value()) {
    error = writer.move_error();
    error->path.segments.emplace_front(
      common::make_unique<iteration::PropertySegment>(property)
    );
    return error;
  }

  return common::nullopt;
}

/**
 * Serialize a tuple of 2 item(s).
 */
template <
  typename T0,
  typename T1,
  typename SerializeT0,
  typename SerializeT1
>
common::optional<SerializationError> SerializeTuple2(
  const std::tuple<
    T0,
    T1
  >& value,
  SelfClosingWriter& writer,
  const SerializeT0& serialize_item0,
  const SerializeT1& serialize_item1
) {
  common::optional<SerializationError> error;

  error = serialize_item0(
    std::get<0>(value),
    writer
  );
  if (error.has_value()) {
    error->path.segments.emplace_front(
      common::make_unique<iteration::IndexSegment>(
        0
      )
    );
    return error;
  }

  error = serialize_item1(
    std::get<1>(value),
    writer
  );
  if (error.has_value()) {
    error->path.segments.emplace_front(
      common::make_unique<iteration::IndexSegment>(
        1
      )
    );
    return error;
  }

  return common::nullopt;
}

/**
 * Serialize a tuple of 6 item(s).
 */
template <
  typename T0,
  typename T1,
  typename T2,
  typename T3,
  typename T4,
  typename T5,
  typename SerializeT0,
  typename SerializeT1,
  typename SerializeT2,
  typename SerializeT3,
  typename SerializeT4,
  typename SerializeT5
>
common::optional<SerializationError> SerializeTuple6(
  const std::tuple<
    T0,
    T1,
    T2,
    T3,
    T4,
    T5
  >& value,
  SelfClosingWriter& writer,
  const SerializeT0& serialize_item0,
  const SerializeT1& serialize_item1,
  const SerializeT2& serialize_item2,
  const SerializeT3& serialize_item3,
  const SerializeT4& serialize_item4,
  const SerializeT5& serialize_item5
) {
  common::optional<SerializationError> error;

  error = serialize_item0(
    std::get<0>(value),
    writer
  );
  if (error.has_value()) {
    error->path.segments.emplace_front(
      common::make_unique<iteration::IndexSegment>(
        0
      )
    );
    return error;
  }

  error = serialize_item1(
    std::get<1>(value),
    writer
  );
  if (error.has_value()) {
    error->path.segments.emplace_front(
      common::make_unique<iteration::IndexSegment>(
        1
      )
    );
    return error;
  }

  error = serialize_item2(
    std::get<2>(value),
    writer
  );
  if (error.has_value()) {
    error->path.segments.emplace_front(
      common::make_unique<iteration::IndexSegment>(
        2
      )
    );
    return error;
  }

  error = serialize_item3(
    std::get<3>(value),
    writer
  );
  if (error.has_value()) {
    error->path.segments.emplace_front(
      common::make_unique<iteration::IndexSegment>(
        3
      )
    );
    return error;
  }

  error = serialize_item4(
    std::get<4>(value),
    writer
  );
  if (error.has_value()) {
    error->path.segments.emplace_front(
      common::make_unique<iteration::IndexSegment>(
        4
      )
    );
    return error;
  }

  error = serialize_item5(
    std::get<5>(value),
    writer
  );
  if (error.has_value()) {
    error->path.segments.emplace_front(
      common::make_unique<iteration::IndexSegment>(
        5
      )
    );
    return error;
  }

  return common::nullopt;
}

